import asyncio,json
from pathlib import Path
from playwright.async_api import async_playwright
ROOT=Path(__file__).parent;R=[]
def rec(n,c):R.append({'name':n,'status':'PASS' if c else 'FAIL'});print(R[-1],flush=True)
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(headless=True);c=await b.new_context(viewport={'width':1280,'height':1800});pg=await c.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
  await pg.goto('http://localhost:8080');await pg.evaluate("localStorage.setItem('ph-lang','en')");await pg.goto('http://localhost:8080/stock/phones');await pg.wait_for_timeout(900)
  await pg.locator('.heading-actions button').last.click();await pg.get_by_role('dialog').last.locator('.scan-field-heading button').first.click()
  await pg.evaluate('''()=>{window.__stops=0;window.__constraints=null;const canvas=document.createElement('canvas');canvas.width=640;canvas.height=480;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,640,480);window.__paint=ctx;window.__canvas=canvas;Object.defineProperty(navigator,'mediaDevices',{configurable:true,value:{getUserMedia:async constraints=>{window.__constraints=constraints;const stream=canvas.captureStream(8);for(const t of stream.getTracks()){const stop=t.stop.bind(t);t.stop=()=>{window.__stops++;stop()}}window.__stream=stream;return stream}}})}''')
  d=pg.get_by_role('dialog').last;await d.get_by_role('button',name='Open camera',exact=True).click();await d.locator('video').wait_for(state='visible');rec('rear preference no audio',await pg.evaluate("window.__constraints.video.facingMode.ideal==='environment'&&!window.__constraints.audio"))
  await d.get_by_role('button',name='Stop camera',exact=True).click();rec('stop camera stops tracks',await pg.evaluate('window.__stream.getTracks().every(t=>t.readyState==="ended")'))
  await d.get_by_role('button',name='Open camera',exact=True).click();await d.locator('video').wait_for(state='visible');await pg.keyboard.press('Escape');rec('Escape stops tracks',await pg.evaluate('window.__stream.getTracks().every(t=>t.readyState==="ended")'))
  await pg.get_by_role('dialog').last.locator('.scan-field-heading button').first.click();d=pg.get_by_role('dialog').last;await d.get_by_role('button',name='Open camera',exact=True).click();await d.locator('video').wait_for(state='visible')
  # Draw a genuine CODE128 frame: decoding is actual ZXing, camera device is a canvas mock.
  await pg.evaluate('''async()=>{const {default:encode}=await import('/node_modules/.vite/deps/jsbarcode.js');const canvas=document.createElement('canvas');encode(canvas,'490154203237518',{format:'CODE128',width:2,height:100,margin:25});window.__paint.fillStyle='white';window.__paint.fillRect(0,0,640,480);window.__paint.drawImage(canvas,(640-canvas.width)/2,160)}''')
  await pg.wait_for_function("window.__stream.getTracks().every(t=>t.readyState==='ended')",timeout=15000);rec('actual 1D frame decoded stops stream',await d.locator('input').input_value()=='490154203237518');await d.screenshot(path=str(ROOT/'decoded_1d.png'));await d.get_by_role('button',name='Use in selected field').click();rec('1D assigned to IMEI1 only',await pg.get_by_role('dialog').last.locator('[name=imei1]').input_value()=='490154203237518' and await pg.get_by_role('dialog').last.locator('[name=imei2]').input_value()=='')
  # actual QR image painted into the same mock video
  await pg.get_by_role('dialog').last.locator('.scan-field-heading button').first.click();d=pg.get_by_role('dialog').last;await d.get_by_role('button',name='Open camera',exact=True).click();await d.locator('video').wait_for(state='visible')
  await pg.evaluate('''async()=>{const {QRCodeWriter,BarcodeFormat}=await import('/node_modules/@zxing/library/esm/index.js');const matrix=new QRCodeWriter().encode('IMEI1:490154203237518;IMEI2:356938035643809',BarcodeFormat.QR_CODE,300,300,new Map());const ctx=window.__paint;ctx.fillStyle='white';ctx.fillRect(0,0,640,480);ctx.fillStyle='black';for(let y=0;y<300;y++)for(let x=0;x<300;x++)if(matrix.get(x,y))ctx.fillRect(x+170,y+90,1,1)}''')
  await pg.wait_for_function('window.__stream.getTracks().every(t=>t.readyState==="ended")',timeout=15000);rec('actual QR encoded identifiers decoded',await d.locator('input').input_value()=='IMEI1:490154203237518;IMEI2:356938035643809');await d.get_by_role('button',name='Assign identifiers').click();rec('verified QR assignment IMEI2',await pg.get_by_role('dialog').last.locator('[name=imei2]').input_value()=='356938035643809')
  await pg.get_by_role('dialog').last.locator('.scan-field-heading button').first.click();d=pg.get_by_role('dialog').last;await d.get_by_role('button',name='Open camera',exact=True).click();await d.locator('video').wait_for(state='visible');await pg.keyboard.press('Escape');rec('final close stops stream',await pg.evaluate('window.__stream.getTracks().every(t=>t.readyState==="ended")')) # full navigation destroys mock realm; actual unmount covered by unit
  rec('no camera runtime errors',not errs);ROOT.joinpath('results.json').write_text(json.dumps(R,indent=2));print('TOTAL',len(R),'PASS',sum(x['status']=='PASS' for x in R),'FAIL',sum(x['status']=='FAIL' for x in R));await b.close()
asyncio.run(main())
